+    for src in [Src::Part, Src::Stock] {
+        let ((at, _, _), warns, posted) = run_on(src, FAR, Casting { coarse: Some(2.5), ..Casting::default() });
+        assert!(warns.contains(&Warning::RapidInStock { at }), "{src:?}: {warns:?}");
